catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    var ga = new GlideAjax('global.HSBCContactManagementUtils');
    ga.addParam('sysparm_name', 'getExistingContactDetails');
    ga.addParam('sysparm_counterparty_code', newValue);
    ga.getXMLAnswer(updateContact);

}

		function updateContact(response) {
        var contactObj = JSON.parse(response);
		g_form.setValue('email_address', contactObj.email_address);
        g_form.setValue('counterparty_description', contactObj.counterparty_description);
        g_form.setValue('business_process', contactObj.business_process);
        g_form.setValue('entity', contactObj.entity);
		if(contactObj.active == 1)
			g_form.setValue('active', 'true');
		if(contactObj.active == 0)
			g_form.setValue('active', 'false');
        g_form.setValue('contact_type', contactObj.contact_type);
        g_form.setValue('contact_number', contactObj.contact_number);
        g_form.setValue('email_automation', contactObj.email_automation);
        g_form.setValue('email_type', contactObj.email_type);
        g_form.setValue('external_or_internal', contactObj.external_or_internal);
        g_form.setValue('high_priority_client', contactObj.high_priority_client);
    }
